mapper.select:
SELECT laa.id, laa.event_type, laa.decision_reason, laa.class_name, laa.method_name, laa.create_time, laa.update_time, laa.create_user, laa.update_user FROM log_authorization_audit laa
AND laa.event_type = #{query.eventType}
AND laa.decision_reason = #{query.decisionReason}
AND laa.class_name LIKE CONCAT('%', #{query.className}, '%' )
AND laa.create_user = #{query.createUserId}
ORDER BY laa.create_time DESC
